# GET /api/sheets/{sheetId}/rates — every rate on the sheet, by grade then from-date (level 0), then those of
# its parent sheets up to three levels up, each with its level (a grade with no rate in force on a date on
# the sheet takes the first level up that has one).
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
  govern: [ readonly-transaction ]
# POST /api/sheets/{sheetId}/rates — set a grade's rate from a date (body: {grade, pct, from, to, user};
# a blank from applies from the beginning of time; an existing grade and from-date keeps the value it replaces as an older version and adds a new one).
# A blank to has no end. A from or to that is not a date (yyyy-MM-dd), or a to before the from, is
# refused (400). A grade other
# than A, B or C, or a pct that is not a number of 0.00 or more with up to two decimals, is refused
# (400) and nothing is stored. A stored change is recorded in the audit file as RATE_SET; a refused
# one records nothing.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.rate.AuditRateSet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
