package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A grade's rate as the front end reads it: the percent with two decimals and the date (yyyy-MM-dd)
 *  it applies from, null when it applies from the beginning of time; and the date it applies through,
 *  null when it has no end; and the level of the sheet it is on: 0 for the sheet's own, 1 for its parent's,
 *  and so on up; and how many versions it has (the newest is the one shown); and, when it is forward-only,
 *  when it was saved (it applies only to claims added after: see {@code RateStore}), else null. */
public record RateResponse(String grade, String pct, String from, String to, int level, int version, Long forward) {
    public static RateResponse of(String grade, BigDecimal pct, LocalDate from, LocalDate to, int version) {
        return of(grade, pct, from, to, 0, version, null);
    }

    public static RateResponse of(String grade, BigDecimal pct, LocalDate from, LocalDate to, int level, int version, Long forward) {
        return new RateResponse(grade, pct.setScale(2).toPlainString(), from == null ? null : from.toString(),
                to == null ? null : to.toString(), level, version, forward);
    }
}
-- A rate is kept as versions: setting a rate for a grade and from-date that already exist keeps the value it
-- replaces as an older version in rate_version and adds a new one. The rate row holds the newest version (the
-- one in force) and its number (version), which counts its versions. Kept in rate_hist too; the history
-- trigger is set again afterwards, as in V69__period_cap.sql.
DROP TRIGGER rate_history;
ALTER TABLE rate ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE rate_hist ADD COLUMN version INT DEFAULT 1 NOT NULL;
CREATE TRIGGER rate_history AFTER INSERT, UPDATE, DELETE ON rate FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';

-- Every version of a rate, numbered from 1 in the order set; the newest is the one in the rate table.
CREATE TABLE rate_version (
    sheet_id  VARCHAR(255)   NOT NULL,
    grade     VARCHAR(1)     NOT NULL,
    from_date DATE           NOT NULL,
    version   INT            NOT NULL,
    pct       DECIMAL(19, 2) NOT NULL,
    to_date   DATE,
    PRIMARY KEY (sheet_id, grade, from_date, version)
);
INSERT INTO rate_version (sheet_id, grade, from_date, version, pct, to_date)
    SELECT sheet_id, grade, from_date, 1, pct, to_date FROM rate;
-- Forward-only rates. Every claim takes the next value of change_seq when it is added (by any path), kept as
-- added_seq (a copy of a claim, on a clone or a transfer, keeps its original's); claims already there take 0.
-- A rate saved with a from-date on or after the sheet's today takes the next value too, as forward_seq, and
-- applies only to claims with a later added_seq; a rate with none (null) applies to every claim. Kept in
-- claim_hist and rate_hist too; the history triggers are set again afterwards, as in V70__rate_versions.sql.
CREATE SEQUENCE change_seq;

DROP TRIGGER claim_history;
ALTER TABLE claim ADD COLUMN added_seq BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ALTER COLUMN added_seq SET DEFAULT NEXT VALUE FOR change_seq;
ALTER TABLE claim_hist ADD COLUMN added_seq BIGINT DEFAULT 0 NOT NULL;
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';

DROP TRIGGER rate_history;
ALTER TABLE rate ADD COLUMN forward_seq BIGINT;
ALTER TABLE rate_hist ADD COLUMN forward_seq BIGINT;
CREATE TRIGGER rate_history AFTER INSERT, UPDATE, DELETE ON rate FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
ALTER TABLE rate_version ADD COLUMN forward_seq BIGINT;

package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The roles assigned per sheet. A user name with none assigned is a clerk; one with a delegation of the
 *  steward role in force on the sheet's today acts as a steward (see {@link DelegationStore}). */
@Repository
public class RoleStore {

    private final JdbcTemplate jdbc;
    private final DelegationStore delegations;
    private final SheetStore sheets;

    public RoleStore(JdbcTemplate jdbc, DelegationStore delegations, SheetStore sheets) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.sheets = sheets;
    }

    /** Every role assigned on the sheet, by user name. */
    public List<RoleResponse> list(String sheetId) {
        return listFrom(sheetId, "sheet_role");
    }

    /** Every role assigned on the sheet at the end of the date (see {@link History}), by user name. */
    public List<RoleResponse> listAsOf(String sheetId, LocalDate date) {
        return listFrom(sheetId, History.asOf("sheet_role", "sheet_id, user_name", date));
    }

    private List<RoleResponse> listFrom(String sheetId, String table) {
        return jdbc.query("SELECT user_name, role FROM " + table + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).shown()),
                sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force, else
     *  the role assigned. */
    public Role find(String sheetId, String user) {
        return delegations.delegator(sheetId, user) != null ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's role as assigned on the sheet, delegations aside: clerk unless assigned otherwise. */
    public Role assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}
