    int version = version(sheetId, grade, from);
    jdbc.update("DELETE FROM rate_version WHERE sheet_id = ? AND grade = ? AND from_date = ? AND version = ?",
            sheetId, grade, at, version);
    int left = jdbc.update("UPDATE rate SET (pct, to_date, version, forward_seq) = (SELECT pct, to_date, version, forward_seq"
            + " FROM rate_version v WHERE v.sheet_id = rate.sheet_id AND v.grade = rate.grade AND v.from_date = rate.from_date"
            + " AND v.version = ?) WHERE sheet_id = ? AND grade = ? AND from_date = ? AND EXISTS (SELECT 1 FROM rate_version v"
            + " WHERE v.sheet_id = ? AND v.grade = ? AND v.from_date = ? AND v.version = ?)",
            version - 1, sheetId, grade, at, sheetId, grade, at, version - 1);
    if (left == 0) {
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date = ?", sheetId, grade, at);
    }
}

